import React from 'react';
import {useFocusMode} from '../../context/focusMode';

const DRAWIO_HTML_BASE64 = '';
const DIAGRAM_ASPECT_RATIO = 1.64;
const DEFAULT_MIN_HEIGHT = 420;
const FOCUS_MIN_HEIGHT = 520;
const MAX_HEIGHT = 980;

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

export default function DrawioArchitectureEmbed() {
  const {isFocusMode} = useFocusMode();
  const containerRef = React.useRef(null);
  const [height, setHeight] = React.useState(620);
  // Defer building the data URL (slicing the ~210 KB base64 string into a URL)
  // and mounting the iframe until the diagram is close to entering the
  // viewport. Once revealed it stays mounted so navigation state is preserved.
  const [isVisible, setIsVisible] = React.useState(false);
  const diagramDataUrl = React.useMemo(
    () => (isVisible ? `data:text/html;base64,${DRAWIO_HTML_BASE64}` : null),
    [isVisible],
  );

  const recalculateHeight = React.useCallback(() => {
    if (typeof window === 'undefined') {
      return;
    }

    const container = containerRef.current;
    if (!container) {
      return;
    }

    const containerWidth = container.clientWidth;
    if (containerWidth === 0) {
      return;
    }

    const minHeight = isFocusMode ? FOCUS_MIN_HEIGHT : DEFAULT_MIN_HEIGHT;
    const viewportMax = window.innerHeight * 0.8;
    const effectiveMax = Math.min(MAX_HEIGHT, viewportMax);
    const desiredHeight = containerWidth / DIAGRAM_ASPECT_RATIO;

    setHeight(clamp(desiredHeight, minHeight, effectiveMax));
  }, [isFocusMode]);

  React.useEffect(() => {
    recalculateHeight();
  }, [recalculateHeight]);

  React.useEffect(() => {
    if (typeof window === 'undefined' || isVisible) return undefined;

    const container = containerRef.current;
    if (!container) return undefined;

    if (typeof IntersectionObserver === 'undefined') {
      // Old browser fallback — just mount immediately.
      setIsVisible(true);
      return undefined;
    }

    const io = new IntersectionObserver(
      (entries) => {
        if (entries.some((e) => e.isIntersecting)) {
          setIsVisible(true);
          io.disconnect();
        }
      },
      {rootMargin: '400px 0px'},
    );

    io.observe(container);
    return () => io.disconnect();
  }, [isVisible]);

  React.useEffect(() => {
    if (typeof window === 'undefined') {
      return undefined;
    }

    const onWindowResize = () => {
      recalculateHeight();
    };

    window.addEventListener('resize', onWindowResize);

    if (typeof ResizeObserver === 'undefined') {
      return () => {
        window.removeEventListener('resize', onWindowResize);
      };
    }

    const observer = new ResizeObserver(() => {
      recalculateHeight();
    });

    const container = containerRef.current;
    if (container) {
      observer.observe(container);
    }

    return () => {
      observer.disconnect();
      window.removeEventListener('resize', onWindowResize);
    };
  }, [recalculateHeight]);

  return (
    <figure style={{margin: 0}}>
      <div
        ref={containerRef}
        style={{
          position: 'relative',
          width: '100%',
          height: `${height}px`,
          transition: 'height 180ms ease',
          border: '1px solid var(--ifm-toc-border-color)',
          borderRadius: '8px',
          overflow: 'hidden',
        }}
      >
        {diagramDataUrl ? (
          <iframe
            src={diagramDataUrl}
            title="OpenLM Platform high-level architecture diagram"
            frameBorder="0"
            loading="lazy"
            sandbox="allow-scripts"
            referrerPolicy="no-referrer"
            style={{width: '100%', height: '100%', border: 0}}
          />
        ) : (
          <div
            aria-hidden="true"
            style={{
              width: '100%',
              height: '100%',
              background: 'var(--ifm-background-surface-color, #f6f7f8)',
            }}
          />
        )}
      </div>
    </figure>
  );
}
